window.kbPageData["cards/d325a24f94644e365ab48e93"] = {"qs":{"江苏 2024 B类 行测#18":{"paper":"江苏 2024 B类 行测","n":18,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",7],"m":[],"task":"判断检察机关能否就假冒饮用水销售提起公益诉讼并以销售额为基数请求惩罚性赔偿。","current_affairs":{"state":"否","event":null,"year":null,"basis":"题目考查食品安全公益诉讼的权限和赔偿规则，作答无需识别特定年份的事件或政策部署。"},"links":[{"id":"k-abd6937053b9eaf1","label":"食品药品安全领域检察机关提起民事公益诉讼的条件","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"食品药品安全领域侵害众多消费者合法权益等损害社会公共利益的行为，在没有前款规定的机关和组织或者前\n款规定的机关和组织不提起诉讼的情况下，可以向人民法院提起诉讼。","why":"该规则明确了食品药品安全案件中检察机关起诉所需的公益受损情形和起诉顺位。","origin":"逐题标记"},{"id":"k-57553598a9256d6d","label":"食品安全民事公益诉讼中检察机关请求惩罚性赔偿的权限及销售额基数","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","why":"参考答案将检察机关的赔偿请求权限与销售额计赔基数列为同一判断。","origin":"逐题标记"}],"stem":"某公司未取得食品药品的生产许可，把当地山泉水净化并罐装，以原装进口饮用水的名义销售，销售额达千万\n元。何某知悉该饮用水为假冒品，便大量购买，并向检察机关举报。对此，下列说法正确的是：","options":["检察机关有权以销售额为基数，请求判令该公司支付惩罚性赔偿金","检察机关有权提起公益诉讼，并将胜诉后所得到的赔偿金归入国库","何某明知该公司销售的是假冒饮用水而购买，无权请求惩罚性赔偿","何某虽购买了假冒饮用水但未造成严重损害，无权请求惩罚性赔偿"],"answer":"A","analysis":"18. 正确答案：A\n解析：\n本题考查法律常识。\n《中华人民共和国民事诉讼法》第五十八条规定：“对污染环境、侵害众多消费者合法权益等损害社会公共利益的行\n为，法律规定的机关和有关组织可以向人民法院提起诉讼。人民检察院在履行职责中发现破坏生态环境和资源保\n护、食品药品安全领域侵害众多消费者合法权益等损害社会公共利益的行为，在没有前款规定的机关和组织或者前\n款规定的机关和组织不提起诉讼的情况下，可以向人民法院提起诉讼。前款规定的机关或者组织提起诉讼的，人民\n检察院可以支持起诉。”《中华人民共和国消费者权益保护法》第五十五条第一款规定：“经营者提供商品或者服务有\n欺诈行为的，应当按照消费者的要求增加赔偿其受到的损失，增加赔偿的金额为消费者购买商品的价款或者接受服\n务的费用的三倍；增加赔偿的金额不足五百元的，为五百元。法律另有规定的，依照其规定。”本题中，该案件属于\n食品药品安全领域侵害众多消费者合法权益的情形，检察机关有权提起诉讼。该公司把当地山泉水净化并罐装的行\n为构成欺诈，应向消费者支付三倍的惩罚性赔偿。何某虽“知假买假”，但根据目前司法实践，该行为并不影响其请求\n支付惩罚性赔偿，只是在数额方面法院会在“生活消费”范围内支持惩罚性赔偿请求。\n故正确答案为A。\n【考点】\n其他法律法规","figs":[],"state":"待核","notes":["参考答案认可以销售额为公益诉讼惩罚性赔偿的计算基数，解析所引条款分别涉及检察机关的起诉资格和消费者按购买价款请求增加赔偿的规则。销售额基数的依据待核。"],"domains":["法律"],"nature":"知识题","current":false},"江苏 2024 B类 行测#19":{"paper":"江苏 2024 B类 行测","n":19,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",7],"m":[],"task":"判断为博取高额奖金购买具有彩票性质的未经许可销售卡片后，能否请求返还购卡款。","current_affairs":{"state":"否","event":null,"year":null,"basis":"题目考查未经许可的彩票类交易所生债务的法律效力。"},"links":[{"id":"k-1b242ff768360f03","label":"未经许可的彩票类博弈交易所生债务的法律效力","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"在经营方未取得国家经营许可的前提下产生的债权债务应评价为非\n法债务，不受国家法律保护。","why":"解析将涉案卡片交易认定为类似购买彩票的行为，并据经营方未获许可判断购卡款返还请求的效力。","origin":"逐题标记"}],"stem":"苏某进入一未经批准销售卡片盲盒的直播间，在主播的推荐下购买了一款兑奖卡片并中了小奖。为中大奖，苏某\n又花费了近万元购买卡片，但无一中奖。苏某便以主播及其所在公司为被告提起诉讼，请求判令返还购买卡片的款\n项。关于本案，下列说法正确的是：","options":["主播的推荐构成欺诈，应向苏某承担赔偿责任","苏某与该公司之间的债权债务关系应受法律保护","苏某为获取博弈利益，无权要求返还购买卡片的款项","苏某后续购买卡片无一中奖，法院应支持其诉讼请求"],"answer":"C","analysis":"19. 正确答案：C\n解析：\n本题考查法律常识。\nA项错误：《中华人民共和国民法典》第一百四十八条规定：“一方以欺诈手段，使对方在违背真实意思的情况下实\n施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。”本题中，主播的行为并不是通过欺诈手\n段，使对方陷入违背真实意思的情况下实施民事法律行为。\nB、D两项错误，C项正确：苏某购买卡片盲盒的行为，并非用于生产生活需要，而是为了获得高额的中奖机会，本\n质上已经脱离了正常的经营者和消费者之间的关系，并非法律规定的一种正常消费行为或销售行为。卡片本身不具\n有相应的价值或者相对高额的价值，苏某又以盲盒类形式购买，从形式上看符合彩票的外在表现形式，属于类似购\n买彩票行为。同时，针对此类购买彩票的行为，在经营方未取得国家经营许可的前提下产生的债权债务应评价为非\n法债务，不受国家法律保护。\n故正确答案为C。\n【考点】\n民法","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false},"江苏 2024 B类 行测#20":{"paper":"江苏 2024 B类 行测","n":20,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",8],"m":[],"task":"判断商场应按何种条件兑现已公布的汽车使用权奖项，以及押金和保险费由谁承担。","current_affairs":{"state":"否","event":null,"year":null,"basis":"题目依据要约和奖项兑付规则判断商场的履行义务。"},"links":[{"id":"k-f3fc27aeb7966f06","label":"商业广告和宣传构成要约的条件","catalog_id":null,"type":"制度与规则","role":"解题依据","field":"answer","quote":"符合要约条件，该抽奖宣传的商业广告应视为要约，具有法律约束力。","why":"抽奖宣传明确了奖品及使用期限，解析据此认定宣传构成有约束力的要约。","origin":"逐题标记"},{"id":"k-e4729357bacc3953","label":"抽奖主办方按已公布条件兑付奖项的义务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"按照前期宣传的内容向中奖\n者兑付奖项，不能事后再增设条件。","why":"商场应按公布的条件交付汽车使用权，因此兑付所需的押金和保险费由商场承担。","origin":"逐题标记"}],"stem":"某商场举行抽奖活动，宣称特等奖为某品牌新能源汽车的一年使用权，并未附加其他条件。韩某中奖后兑奖时，\n商场却根据与汽车厂商的合同，要求韩某交纳10万元押金和汽车使用保险费。对此，下列说法正确的是：","options":["商场的抽奖宣传是商业广告，没有法律约束力","商场实施了欺诈，韩某有权要求商场承担惩罚性赔偿","韩某有权获得汽车使用权，商场需支付押金和保险费","韩某有权直接起诉商场和汽车厂商，要求履行合同义务"],"answer":"C","analysis":"20. 正确答案：C\n解析：\n本题考查法律常识。\nA项错误：《中华人民共和国民法典》第四百七十三条规定：“要约邀请是希望他人向自己发出要约的表示。拍卖公\n告、招标公告、招股说明书、债券募集办法、基金招募说明书、商业广告和宣传、寄送的价目表等为要约邀请。商\n业广告和宣传的内容符合要约条件的，构成要约。”由于商场的抽奖活动宣传已经明确到具体的奖品类型与使用期\n限，符合要约条件，该抽奖宣传的商业广告应视为要约，具有法律约束力。\nB项错误：《中华人民共和国民法典》第一百四十八条规定：“一方以欺诈手段，使对方在违背真实意思的情况下实\n施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。”商场的行为并不是以欺诈手段，并使消费\n者违背真实意思实施民事法律行为。\nC项正确：《中华人民共和国民法典》第一百四十条规定：“行为人可以明示或者默示作出意思表示。沉默只有在有\n法律规定、当事人约定或者符合当事人之间的交易习惯时，才可以视为意思表示。”由于商场在抽奖活动前期宣传中\n对“中奖需支付押金及使用期间的保险费用”这一事项未进行明示，商场应秉持诚信原则，按照前期宣传的内容向中奖\n者兑付奖项，不能事后再增设条件。韩某无须支付押金和保险费。\nD项错误：《中华人民共和国民法典》第四百六十五条规定：“依法成立的合同，受法律保护。依法成立的合同，仅\n对当事人具有法律约束力，但是法律另有规定的除外。”合同具有相对性，韩某仅有权直接起诉商场，要求其履行合\n同义务。\n故正确答案为C。\n【考点】\n民法","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false}},"materialFiles":{},"terms":{"k-abd6937053b9eaf1":{"id":"k-abd6937053b9eaf1","mode":"k","type":"制度与规则","title":"食品药品安全领域的检察民事公益诉讼","qs":[],"count":1},"k-57553598a9256d6d":{"id":"k-57553598a9256d6d","mode":"k","type":"制度与规则","title":"食品安全民事公益诉讼的惩罚性赔偿","qs":[],"count":1},"k-1b242ff768360f03":{"id":"k-1b242ff768360f03","mode":"k","type":"制度与规则","title":"彩票式盲盒交易的效力与退款","qs":[],"count":1},"k-f3fc27aeb7966f06":{"id":"k-f3fc27aeb7966f06","mode":"k","type":"制度与规则","title":"商业广告和宣传构成要约的条件","qs":[],"count":1},"k-e4729357bacc3953":{"id":"k-e4729357bacc3953","mode":"k","type":"制度与规则","title":"抽奖主办方按公布条件兑奖","qs":[],"count":1}},"questions":{}};
